# Read the entire session file and parse demos
import json, re, os

d = os.environ['RLM_SESSION_DIR']
path = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'
content = open(path).read()

# Extract all grid lines (rows of numbers)
all_lines = content.split('\n')
in_demo = False
demo_data = {}
grid_rows = []

for line in all_lines:
    # Check for Demo/Test input header
    m = re.match(r'(Demo pair \d+ (?:input|output)|Test input)\s*\((\d+)x(\d+)\):', line)
    if m:
        kind, h, w = m.groups()
        print(f"\n=== {kind} {h}x{w} ===")
        if 'Test input' in kind:
            demo_data['test'] = []
        else:
            name_match = re.search(r'Demo pair (\d+)', kind)
            if name_match:
                demo_name = f"pair_{name_match.group(1)}"
                demo_data[demo_name] = []
        grid_rows = []
        in_demo = True
        continue

    # Collect grid rows
    if in_demo and grid_rows and len(grid_rows) < int(h):
        parts = line.strip().split()
        if parts and all(x.isdigit() for x in parts[:20]):
            row = [int(x) for x in parts[:12]]  # assume width up to 12
            grid_rows.append(row)
        elif line.strip() and line.strip()[0].isdigit():
            try:
                row = [int(x) for x in line.split()[:12]]
                grid_rows.append(row)
            except:
                pass

    if len(grid_rows) >= int(h):
        break

print("\n\nAll demos collected:")
for key, val in demo_data.items():
    print(f"{key}: {len(val)} rows")
    if val:
        print(val[0])

