# Try to find all callable items that might be tool wrappers
import inspect

def find_callable_tools():
    found = {}
    for name, obj in globals().items():
        if callable(obj) and hasattr(obj, '__name__'):
            try:
                sig = inspect.signature(obj)
                # Check if it looks like a tool function (takes text args, returns dict)
                found[name] = str(sig)[:100]
            except:
                pass
    return list(found.keys())[:20]

print("Possible tools:", find_callable_tools())

# Check if request_demos needs special importing
