for name, obj in globals().items():
    if hasattr(obj, '__wrapped__') or getattr(obj, '__is_tool__', False):
        print(f"Potential tool: {name}")

# Check if there's a global namespace where tools are registered
globals_dict = globals()

# Search for any object that has 'request' or 'demo' in its attributes
for name, obj in globals_dict.items():
    if hasattr(obj, '__dict__'):
        attrs = [a for a in obj.__dict__.keys() if 'request' in a.lower() or 'demo' in a.lower()]
        if attrs:
            print(f"{name} has {attrs}")

# Search for tool-to-function mapping in all accessible namespaces
found_mapping = False

for ns_name in ['globals', 'locals', 'builtins']:
    ns = globals() if ns_name == 'globals' else (sys._getframe().f_locals if ns_name == 'locals' else builtins)

    # Look for dict-like structures or mappings
    for item in ns.values():
        if isinstance(item, dict):
            keys = list(item.keys())[:10]
            print(f"{ns_name} has dict with keys: {keys}")
            found_mapping = True
            break

if not found_mapping:
    print("No obvious mapping found")

# Check what tools are actually importable via different mechanisms
import sys

tool_candidates = ['arc', 'request_demos', 'demo', 'submit']
for tool_name in tool_candidates:
    found = False
    for mod_name, mod_obj in sys.modules.items():
        if mod_name == tool_name:
            print(f"Found {tool_name} as module")
            found = True
            break

    # Also check for function references
    for name, obj in globals().items():
        if name == tool_name and callable(obj):
            print(f"Found {tool_name} as function")
            found = True
            break

    if not found:
        print(f"{tool_name}: not found")

# Direct access to globals by name
for name in ['request_demos', 'submit', 'arc']:
