def get_regions(grid):
    h, w = len(grid), len(grid[0])
    visited = set()
    regions = defaultdict(list)

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 and (r, c) not in visited:
                color = grid[r][c]
                comp = []
                queue = [(r,c)]
                while queue:
                    cr, cc = queue.pop(0)
                    if (cr, cc) in visited or (cr, cc) in comp:
                        continue
                    visited.add((cr, cc))
                    comp.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color and (nr, nc) not in visited:
                            queue.append((nr, nc))
                regions[color].append(comp)

    return dict(regions)

